#include <stdio.h>
#include <limits.h>

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    long long colSum[M];
    for (int j = 0; j < M; j++) {
        colSum[j] = 0;
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int val;
            scanf("%d", &val);
            colSum[j] += val;
        }
    }

    long long ans = LLONG_MAX;
    for (int j = 0; j < M - 1; j++) {
        long long cost = colSum[j] < colSum[j+1] ? colSum[j] : colSum[j+1];
        if (cost < ans) ans = cost;
    }

    printf("%lld\n", ans);
    return 0;
}
